class Solution {
public:
    int numKLenSubstrNoRepeats(string s, int k) {
        if (k > 26 || k > (int)s.size()) return 0;
        vector<int> freq(26, 0);
        int distinct = 0;
        for (int i = 0; i < k; ++i) {
            if (++freq[s[i] - 'a'] == 1) distinct++;
        }
        int count = (distinct == k ? 1 : 0);
        for (int i = k; i < (int)s.size(); ++i) {
            if (++freq[s[i] - 'a'] == 1) distinct++;
            if (--freq[s[i - k] - 'a'] == 0) distinct--;
            if (distinct == k) count++;
        }
        return count;
    }
};

class Solution {
    public int numKLenSubstrNoRepeats(String s, int k) {
        if (k > 26 || k > s.length()) return 0;
        int[] freq = new int[26];
        int distinct = 0;
        for (int i = 0; i < k; i++) {
            if (++freq[s.charAt(i) - 'a'] == 1) distinct++;
        }
        int count = (distinct == k ? 1 : 0);
        for (int i = k; i < s.length(); i++) {
            if (++freq[s.charAt(i) - 'a'] == 1) distinct++;
            if (--freq[s.charAt(i - k) - 'a'] == 0) distinct--;
            if (distinct == k) count++;
        }
        return count;
    }
}

var numKLenSubstrNoRepeats = function(s, k) {
    if (k > 26 || k > s.length) return 0;
    const freq = new Array(26).fill(0);
    let distinct = 0;
    const code = (c) => c.charCodeAt(0) - 97;
    for (let i = 0; i < k; i++) {
        if (++freq[code(s[i])] === 1) distinct++;
    }
    let count = (distinct === k ? 1 : 0);
    for (let i = k; i < s.length; i++) {
        if (++freq[code(s[i])] === 1) distinct++;
        if (--freq[code(s[i - k])] === 0) distinct--;
        if (distinct === k) count++;
    }
    return count;
};
